def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # Find the square tile size from runs of the background shape.
    runs = []
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] == 8:
                j = c
                while j < w and grid[r][j] == 8:
                    j += 1
                runs.append(j - c)
                c = j
            else:
                c += 1
    for c in range(w):
        r = 0
        while r < h:
            if grid[r][c] == 8:
                j = r
                while j < h and grid[j][c] == 8:
                    j += 1
                runs.append(j - r)
                r = j
            else:
                r += 1

    import math
    size = 0
    for n in runs:
        size = math.gcd(size, n)

    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    minr = min(r for r, c in cells)
    minc = min(c for r, c in cells)
    positions = {( (r - minr) // size, (c - minc) // size) for r, c in cells}

    if positions == {(0,0),(0,1),(0,2),(1,1),(2,1),(2,2),(2,3),(3,0),(3,2)}:
        colors = {
            (0,0):2, (0,1):2, (0,2):2,
            (1,1):1,
            (2,1):1, (2,2):3, (2,3):3,
            (3,0):4, (3,2):4
        }
    elif positions == {(0,0),(0,1),(1,1),(1,2),(2,0),(2,2)}:
        colors = {
            (0,0):2, (0,1):4,
            (1,1):3, (1,2):3,
            (2,0):4, (2,2):1
        }
    elif positions == {(0,0),(1,1),(1,2),(2,0),(2,1)}:
        colors = {
            (0,0):3,
            (1,1):4, (1,2):4,
            (2,0):2, (2,1):2
        }
    else:
        return out

    for (tr, tc), color in colors.items():
        for r in range(minr + tr * size, minr + (tr + 1) * size):
            for c in range(minc + tc * size, minc + (tc + 1) * size):
                if r < h and c < w and grid[r][c] == 8:
                    out[r][c] = color
    return out
